<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title><?= $page === 'login' ? 'Sign in' : 'Create account' ?> | BloodBridge</title><link rel="stylesheet" href="assets/style.css"></head><body class="auth-page"><div class="auth-visual"><a class="brand light" href="index.php"><span class="brand-mark">+</span><span>blood<span>bridge</span></span></a><div><p class="eyebrow">A connected care network</p><h1>When time matters,<br><em>community moves.</em></h1><p>Find a match, raise a request, and make every donation count.</p></div><div class="quote">“The gift of blood is the gift of life.”<small>— World Health Organization</small></div></div><main class="auth-card"><div class="auth-inner"><span class="eyebrow">Welcome to BloodBridge</span><h2><?= $page === 'login' ? 'Sign in to your account' : 'Create your account' ?></h2><p class="muted"><?= $page === 'login' ? 'Manage donations, requests, and your impact.' : 'Join a network built for faster, safer help.' ?></p><?php $flash = take_flash(); if ($flash): ?><div class="toast error"><?= h($flash['message']) ?></div><?php endif; ?><form method="post" class="form-stack"><?php if ($page === 'register'): ?><input type="hidden" name="action" value="register"><label>Full name<input required name="name" placeholder="e.g. Amina Rahman"></label><label>Account type<select name="role"><option value="recipient">Recipient / Patient</option><option value="donor">Donor</option></select></label><label>Blood group<select name="blood_group"><?php foreach (['A+','A-','B+','B-','AB+','AB-','O+','O-'] as $group): ?><option><?= $group ?></option><?php endforeach; ?></select></label><label>Phone<input required name="phone" placeholder="+880 1XXX-XXXXXX"></label><label>Location<input required name="location" placeholder="Dhaka, Bangladesh"></label><?php else: ?><input type="hidden" name="action" value="login"><label>Email address<input required type="email" name="email" 